"""Generate the static front page from the reviewed catalog. No network calls."""
import json,pathlib,html
root=pathlib.Path(__file__).resolve().parents[1]
data=json.loads((root/'catalog.json').read_text(encoding='utf-8'))
esc=lambda s:html.escape(s,quote=True)
workshops=sum(p['bundled'] and p.get('kind')!='reference shelf' for p in data['projects'])
shelves=sum(p.get('kind')=='reference shelf' for p in data['projects'])
art=[
'<rect x="38" y="24" width="164" height="92" rx="8"/><path d="M38 47h164M93 117v20m-31 0h62M64 69l14 12-14 12m30 0h22"/><circle cx="174" cy="139" r="14"/><path d="M174 124v-13m-15 28h-22"/>',
'<path d="M86 33h68v74H86zM107 33V20m-15 88v22m57-22v22M85 51H64v42m91-42h21v42"/><circle cx="105" cy="61" r="6"/><circle cx="136" cy="61" r="6"/><path d="M105 87h31M54 145h135m-13-7 13 7-13 7"/>',
'<circle cx="96" cy="87" r="59"/><path d="M37 87h118M96 28c-38 30-38 88 0 118m0-118c38 30 38 88 0 118M49 54h94M49 119h94"/><path d="M156 68c-2-27 43-31 47-4 25-4 36 29 9 35h-54c-24-4-19-30-2-31z"/>',
'<path d="M40 28h46v46H40zM56 44h14v14H56zM150 28h46v46h-46zM166 44h14v14h-14zM40 105h46v46H40zM56 121h14v14H56zM104 28v24h25V28m-25 45v20h23V73m23 18h23v24h23v24h-22v12m-69-45v22h25v23m-25-12h-3m47-8v20h-17"/>',
'<circle cx="119" cy="87" r="43"/><ellipse cx="119" cy="87" rx="94" ry="24" transform="rotate(-25 119 87)"/><path d="M119 23v-7m64 19 8-8M57 126l-9 9M191 125l9 9"/>',
'<path d="M34 38h75l11 10 11-10h75v103h-75l-11 10-11-10H34zM120 48v103M51 60h42m-42 19h42m-42 19h42m54-38h42m-42 19h42m-42 19h42"/>']
art.append('<path d="M42 44h156M42 136h156M65 44v92m51-92 15 92 18-92M166 44v92"/><circle cx="120" cy="89" r="70"/>')
cards=[]
for i,p in enumerate(data['projects']):
 links=f'<a class="open" href="{esc(p["entry"] or p["original"])}">'+('Open reference shelf' if p.get('kind')=='reference shelf' else 'Open workshop' if p['bundled'] else 'Visit project')+' <span aria-hidden="true">↗</span></a>'
 if p['download']: links+=f'<a href="{esc(p["download"])}" download>Download ZIP</a>'
 original=f'<a href="{esc(p["original"])}">'+p.get('originLabel', 'Shelf source' if p.get('kind')=='reference shelf' else 'Original website')+' ↗</a>'
 if p['source']: original+=f' · <a href="{esc(p["source"])}">Original source ↗</a>'
 search=' '.join(str(p.get(k,'')) for k in ['title','topic','hook','description','starter']).lower()
 cards.append(f'''<article class="project art-{i}" data-topic="{esc(p['topic'])}" data-search="{esc(search)}"><div class="illustration"><svg viewBox="0 0 240 174" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">{art[i % len(art)]}</svg><span class="serial">0{i+1}</span></div><div class="project-body"><p class="eyebrow">{esc(p['topic'])} · {'Reference shelf' if p.get('kind')=='reference shelf' else 'Bundled workshop' if p['bundled'] else 'Linked project'}</p><h3>{esc(p['title'])}</h3><p class="hook">{esc(p['hook'])}</p><p>{esc(p['description'])}</p><p class="starter"><strong>Start here</strong> {esc(p['starter'])}</p><div class="actions">{links}</div><details><summary>Original home &amp; package details</summary><p>{original}</p><p>{esc(p['detail'])}. {'The shelf is packaged for offline browsing; its external reading destinations need internet.' if p.get('kind')=='reference shelf' else 'Core activities are included in the portable collection; live services and optional media need internet.' if p['bundled'] else 'This listing links to its original home; its source and media are not bundled.'}</p></details></div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Free educational workshops for children and curious adults. Explore computing, robotics, weather, codes, and space. Curated by Steven Powell."><title>Everyday Cool · Curiosity belongs to everyone</title><link rel="stylesheet" href="assets/hub.css"><script src="assets/hub.js" defer></script></head><body><a class="skip" href="#collection">Skip to workshops</a><header><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">✳</span> Everyday Cool<span class="edition">A GROWING COLLECTION</span></a><nav aria-label="Main navigation"><a href="#collection">Explore</a><a href="#contribute">Contribute</a><a href="https://github.com/caeled/everyday-cool">GitHub ↗</a></nav></header><main><section class="hero"><div><p class="eyebrow">FOR OUR CHILDREN. FOR THE CURIOUS.</p><h1>Ordinary curiosity.<br><em>Extraordinary places.</em></h1><p class="lead">A robot’s next move. A faraway storm. A message hiding in little squares. Pick a question and see where it takes you.</p><div class="hero-actions"><a class="button" href="#collection">Find something cool <span aria-hidden="true">↓</span></a><a class="text-link" href="https://github.com/caeled/everyday-cool/archive/refs/heads/main.zip">Take the collection with you ↗</a></div><p class="fine">Free to explore. Built with AI assistance. Curated by a human.</p></div><div class="hero-art" aria-hidden="true"><span class="orbit orbit-a"></span><span class="orbit orbit-b"></span><span class="planet">?</span><span class="tile t-one">&lt;/&gt;</span><span class="tile t-two">☀</span><span class="tile t-three">✦</span><span class="art-note">ASK → TRY → NOTICE → UNDERSTAND</span></div></section><div class="principles"><span>✳ Free learning, always</span><span>↗ Made to explore and share</span><span>◎ '''+str(workshops)+''' workshops to carry offline</span></div><section id="collection" aria-labelledby="collection-title"><div class="section-top"><div><p class="eyebrow">THE COLLECTION / START ANYWHERE</p><h2 id="collection-title">What has you curious?</h2></div><p>For kids and adults.<br>No permission to be curious required.</p></div><div class="finder"><div><label for="search">Find a subject or an idea</label><input id="search" type="search" placeholder="Try robots, Antarctica, encryption…" autocomplete="off"></div><div class="filters" role="group" aria-label="Filter workshops by topic"><button type="button" data-filter="all" aria-pressed="true">Everything</button><button type="button" data-filter="Computing" aria-pressed="false">Computing</button><button type="button" data-filter="Robotics" aria-pressed="false">Robotics</button><button type="button" data-filter="Earth &amp; space" aria-pressed="false">Earth &amp; space</button><button type="button" data-filter="Codes &amp; communication" aria-pressed="false">Codes &amp; communication</button><button type="button" data-filter="Reading &amp; reference" aria-pressed="false">Reading &amp; reference</button><button type="button" data-filter="Math" aria-pressed="false">Math</button></div></div><p id="results" class="fine" role="status">'''+str(len(data['projects']))+''' projects · '''+str(workshops)+''' bundled workshops + '''+str(shelves)+''' reference shelf</p><div class="projects">'''+''.join(cards)+'''</div><p id="empty" hidden>No matches yet. Try another word or choose Everything.</p><aside class="continuity"><span aria-hidden="true">↗</span><div><h3>A new home. The originals stay.</h3><p>The existing projects remain at their original addresses and continue to be maintained. Everyday Cool is the curated home for this collection and future additions. These are independent copies, updated through review; original websites and source histories are linked on each card.</p></div></aside></section><section id="contribute" class="contribute"><div><p class="eyebrow">OPEN TO IDEAS / CAREFULLY CURATED</p><h2>Something worth<br><em>giving away.</em></h2><p>This collection began with a simple idea: use AI to build things that make someone want to learn. Offer them freely. Keep making them better.</p><p>Curated by Steven Powell. Bring a good question, a clearer explanation, a translation, or a workshop of your own. Develop it in your own fork, then propose it for the collection.</p><a class="button light" href="https://github.com/caeled/everyday-cool/issues/new/choose">Suggest something cool ↗</a></div><div class="steps"><article><span>01</span><h3>Make it useful</h3><p>A real activity, a clear explanation, and sources someone can follow.</p></article><article><span>02</span><h3>Keep it freely accessible</h3><p>No subscriptions, prompt-pack sales, ads, or affiliate funnels in the official collection.</p></article><article><span>03</span><h3>Share it for review</h3><p>Contributions are proposals. Steven decides what joins the official collection.</p></article><a href="CONTRIBUTING.md">Read the contribution guide ↗</a><a href="GOVERNANCE.md">How the collection is curated ↗</a></div></section><section class="license-note"><h2>Use it. Teach from it. Make it yours.</h2><p>Original hub code is MIT; original lessons are CC BY 4.0. Keep credit and applicable notices. Bundled projects and external resources retain their own terms. These free licenses permit commercial reuse; our official collection stays free and independently made forks are not automatically endorsed.</p><div class="actions"><a href="LICENSE">Code license</a><a href="LICENSE-CONTENT.md">Lesson license</a><a href="THIRD-PARTY.md">Credits &amp; external resources</a><a href="README.md">Portable guide</a></div></section></main><footer><a class="brand" href="#">Everyday Cool <span aria-hidden="true">✳</span></a><p>Steven Powell · Curiosity belongs to everyone.</p><a href="https://github.com/caeled/everyday-cool">Open project ↗</a></footer></body></html>'''
(root/'index.html').write_text(page,encoding='utf-8')
print('Static catalog built:',len(cards),'projects')
